types.declaration:
export interface Rate {
    num: number;
    den: number;
}

export interface MainTimelineContext {
    kind: 'main';
}

export interface CompositionTimelineContext {
    kind: 'composition';
    id: string;
    name: string;
}

export interface ProjectInfo {
    id: string;
    name: string;
    description: string;
    width: number;
    height: number;
    fps: Rate;
    backgroundColor?: string;
    createdAt: number;
    updatedAt: number;
}

export interface ProjectCreateInput {
    name: string;
    width: number;
    height: number;
    fps: Rate;
}

export interface ProjectPatch {
    width?: number;
    height?: number;
    fps?: Rate;
    backgroundColor?: string;
}

export interface MediaInfo {
    id: MediaId;
    fileName: string;
    mimeType: string;
    type: MediaType;
    fileSize: number;
    duration: Seconds;
    width: number;
    height: number;
    fps: number;
    codec: string;
    bitrate: number;
    createdAt: number;
    updatedAt: number;
}

export interface MediaImportOptions {
    storageMode?: 'copy' | 'link';
}

export interface MediaFilter {
    type?: MediaType;
}

export interface SubclipInfo {
    id: SubclipId;
    mediaId: MediaId;
    name: string;
    startFrame: SourceFrame;
    endFrame: SourceFrame;
    sourceFps: number;
    createdAt: number;
    valid: boolean;
    invalidReason?: SubclipInvalidReason;
}

export interface SubclipCreateInput {
    mediaId: MediaId;
    startFrame: SourceFrame;
    endFrame: SourceFrame;
    name?: string;
}

export interface SubclipFilter {
    mediaId?: MediaId;
}

export interface TrackInfo {
    id: TrackId;
    name: string;
    kind?: TrackKind;
    height: number;
    locked: boolean;
    syncLock?: boolean;
    visible: boolean;
    muted: boolean;
    solo: boolean;
    volume?: number;
    color?: string;
    order: number;
}

export interface TrackAddInput {
    kind: TrackKind;
    name?: string;
    position?: number;
}

export interface TrackPatch {
    name?: string;
    locked?: boolean;
    syncLock?: boolean;
    visible?: boolean;
    muted?: boolean;
    solo?: boolean;
    volume?: number;
    color?: string;
}

export interface ClipTransform {
    x?: number;
    y?: number;
    width?: number;
    height?: number;
    anchorX?: number;
    anchorY?: number;
    rotation?: number;
    flipHorizontal?: boolean;
    flipVertical?: boolean;
    opacity?: number;
    cornerRadius?: number;
}

export interface ClipInfo {
    id: ClipId;
    trackId: TrackId;
    type: ClipType;
    from: Frame;
    durationInFrames: Frame;
    label: string;
    mediaId?: MediaId;
    compositionId?: string;
    trimStart?: SourceFrame;
    trimEnd?: SourceFrame;
    sourceStart?: SourceFrame;
    sourceEnd?: SourceFrame;
    sourceDuration?: SourceFrame;
    sourceFps?: number;
    speed?: number;
    isReversed?: boolean;
    volume?: number;
    audioFadeIn?: Seconds;
    audioFadeOut?: Seconds;
    fadeIn?: Seconds;
    fadeOut?: Seconds;
    transform?: ClipTransform;
    text?: string;
    color?: string;
}

export interface ClipAddInput {
    mediaId: MediaId;
    trackId: TrackId;
    from: Frame;
    durationInFrames?: Frame;
    label?: string;
    sourceStart?: SourceFrame;
    sourceEnd?: SourceFrame;
}

export interface ClipPatch {
    label?: string;
    volume?: number;
    audioFadeIn?: Seconds;
    audioFadeOut?: Seconds;
    fadeIn?: Seconds;
    fadeOut?: Seconds;
    muted?: boolean;
    transform?: ClipTransform;
}

export interface ClipFilter {
    trackId?: TrackId;
    type?: ClipType;
}

export interface ClipRemoveOptions {
    ripple?: boolean;
}

export interface ClipDuplicateOptions {
    count?: number;
    offsetFrames?: Frame;
}

export interface SpeedKey {
    frame: Frame;
    speed: number;
}

export interface ClipSpeedCurve {
    keys: SpeedKey[];
    averageSpeed: number;
}

export interface MotionBlurSettings {
    shutterDegrees: 90 | 180 | 270 | 360;
    blendSlowMotion?: boolean;
}

export interface SpeedPresetOptions {
    peak?: number;
    rampFrames?: number;
}

export interface ClipLookInfo {
    id: string;
    intensity: number;
}

export interface ClipLookRequest {
    id: string;
    intensity?: number;
}

export interface LookAddInput {
    text: string;
    fileName: string;
    name?: string;
}

export interface LookInfo {
    id: string;
    name: string;
    fileName: string;
    size: number;
}

export interface ClipStabilization {
    enabled: boolean;
    method: string;
    params: Record<string, number>;
    fov: number;
    horizonLockPercent: number;
    horizonLockRoll: number;
    adaptiveZoomSeconds: number;
}

export interface StabilizationPatch {
    smoothness?: number;
    fov?: number;
    horizonLockPercent?: number;
    horizonLockRoll?: number;
    adaptiveZoomSeconds?: number;
}

export interface ShadowMarkInput {
    x: number;
    y: number;
    sourceFrame?: number;
    radius?: number;
}

export interface ShadowMarkInfo {
    x: number;
    y: number;
    sourceFrame: number;
    radius: number;
}

export interface ShadowQuote {
    seconds: number;
    costCredits: number;
    creditsPerSecond: number;
    availableCredits: number;
    enough: boolean;
}

export interface ShadowRangeInfo {
    startFrame: number;
    endFrame: number;
}

export interface ShadowState {
    mark: ShadowMarkInfo | null;
    stage: string;
    progress: number;
    ranges: ShadowRangeInfo[];
    quote: ShadowQuote | null;
    error: string | null;
    needsSignIn: boolean;
    cleanedPieces: number;
}

export interface ShadowFollowResult {
    ranges: ShadowRangeInfo[];
    quote: ShadowQuote | null;
}

export interface ShadowCleanResult {
    creditsSpent: number;
    ranges: ShadowRangeInfo[];
    cleanedPieces: number;
}

export interface TitleShadow {
    offsetX: number;
    offsetY: number;
    blur: number;
    color: string;
}

export interface TitleStroke {
    width: number;
    color: string;
}

export interface TitleStyle {
    fontSize?: number;
    fontFamily?: string;
    fontWeight?: 'normal' | 'medium' | 'semibold' | 'bold';
    fontStyle?: 'normal' | 'italic';
    underline?: boolean;
    color?: string;
    letterSpacing?: number;
    backgroundColor?: string | null;
    backgroundRadius?: number;
    textAlign?: 'left' | 'center' | 'right';
    verticalAlign?: 'top' | 'middle' | 'bottom';
    lineHeight?: number;
    textPadding?: number;
    textShadow?: TitleShadow | null;
    stroke?: TitleStroke | null;
}

export interface TitleAddInput {
    trackId: TrackId;
    from: Frame;
    durationInFrames: Frame;
    text: string;
    style?: TitleStyle;
}

export interface TitlePatch {
    text?: string;
    style?: TitleStyle;
}

export interface EffectParamInfo {
    type: 'number' | 'boolean' | 'select' | 'color' | 'point' | 'json' | 'text';
    label: string;
    default: EffectParamValue;
    min?: number;
    max?: number;
    step?: number;
    options?: Array<{
        value: string;
        label: string;
    }>;
    animatable?: boolean;
}

export interface EffectTypeInfo {
    id: string;
    name: string;
    category: 'color' | 'blur' | 'distort' | 'stylize' | 'keying';
    params: Record<string, EffectParamInfo>;
}

export interface EffectInfo {
    id: EffectId;
    type: string;
    params: Record<string, EffectParamValue>;
    enabled: boolean;
}

export interface EffectPatch {
    params?: Record<string, EffectParamValue>;
    enabled?: boolean;
}

export interface KeyframeInfo {
    id: KeyframeId;
    property: KeyframeProperty;
    frame: Frame;
    value: number;
    easing: Easing;
    bezier?: KeyframeBezier;
    spring?: KeyframeSpring;
}

export interface KeyframeBezier {
    x1: number;
    y1: number;
    x2: number;
    y2: number;
}

export interface KeyframeSpring {
    tension: number;
    friction: number;
    mass: number;
}

export interface KeyframePatch {
    value?: number;
    easing?: Easing;
    bezier?: KeyframeBezier;
    spring?: KeyframeSpring;
    frame?: Frame;
}

export interface TransitionBezierPoints {
    x1: number;
    y1: number;
    x2: number;
    y2: number;
}

export interface TransitionInfo {
    id: TransitionId;
    type: 'crossfade';
    presentation: string;
    timing: TransitionTiming;
    leftClipId: ClipId;
    rightClipId: ClipId;
    trackId: TrackId;
    durationInFrames: Frame;
    direction?: TransitionDirection;
    alignment?: number;
    bezierPoints?: TransitionBezierPoints;
    presetId?: string;
    properties?: Record<string, unknown>;
}

export interface TransitionAddInput {
    left: ClipId;
    right: ClipId;
    presentation?: string;
    durationInFrames?: Frame;
    timing?: TransitionTiming;
    direction?: TransitionDirection;
    alignment?: number;
}

export interface TransitionPatch {
    presentation?: string;
    durationInFrames?: Frame;
    timing?: TransitionTiming;
    direction?: TransitionDirection;
    alignment?: number;
}

export interface MarkerInfo {
    id: MarkerId;
    frame: Frame;
    label?: string;
    color: string;
}

export interface MarkerAddInput {
    frame: Frame;
    label?: string;
    color?: string;
}

export interface MarkerPatch {
    frame?: Frame;
    label?: string;
    color?: string;
}

export interface RangeInfo {
    in: Frame | null;
    out: Frame | null;
}

export interface SelectionInfo {
    clips: ClipId[];
    tracks: TrackId[];
    marker: MarkerId | null;
    transition: TransitionId | null;
}

export interface SelectionPatch {
    clips?: ClipId[];
    tracks?: TrackId[];
    marker?: MarkerId | null;
    transition?: TransitionId | null;
}

export interface PlaybackInfo {
    frame: Frame;
    playing: boolean;
    rate: number;
    loop: boolean;
}

export interface ExportSettingsInfo {
    codec: ExportCodec;
    quality: ExportQuality;
    resolution: {
        width: number;
        height: number;
    };
    rateControl?: ExportRateControl;
    videoBitrate?: number;
    smartCopy?: boolean;
    mode: ExportMode;
    videoContainer?: ExportVideoContainer;
    audioContainer?: ExportAudioContainer;
    subtitleMode?: ExportSubtitleMode;
    renderWholeProject?: boolean;
}

export interface ExportPresetInfo {
    id: string;
    label: string;
    settings: ExportSettingsPatch;
    numbers: {
        width: number;
        height: number;
        fps: number;
        codec: ExportCodec;
        bitrate: number;
    };
}

export interface ExportStartInput {
    settings?: ExportSettingsPatch;
    inPoint?: Frame | null;
    outPoint?: Frame | null;
    name?: string;
}

export interface ExportWaitOptions {
    timeoutMs?: number;
}

export interface ExportJobInfo {
    id: string;
    name: string;
    projectId?: string;
    status: ExportJobStatus;
    progress: number;
    phase?: ExportPhase;
    progressMessage?: string;
    renderedFrames?: number;
    totalFrames?: number;
    inPoint: Frame | null;
    outPoint: Frame | null;
    durationFrames: Frame;
    exportMode: ExportMode;
    fileName: string;
    savedPath?: string;
    fileSize?: number;
    error?: string;
    createdAt: number;
    startedAt?: number;
    finishedAt?: number;
}

export interface EntityRef {
    kind: EntityKind;
    id: string;
    clip?: ClipId;
}

export interface UpdatedEntityRef extends EntityRef {
    fields: string[];
}

export interface CommandInfo {
    type: string;
    payload?: Record<string, unknown>;
}

export interface Changes {
    commands: CommandInfo[];
    added: EntityRef[];
    removed: EntityRef[];
    updated: UpdatedEntityRef[];
    undoSteps: number;
}

export interface TransactionResult<T> {
    value: T;
    changes: Changes;
}

export interface SdkMethodReference {
    name: string;
    signature: string;
    summary: string;
    mapsTo: string;
    throws: string[];
    example: string;
}

export interface SdkNamespaceReference {
    name: string;
    summary: string;
    methods: SdkMethodReference[];
}

export interface SdkTypeReference {
    name: string;
    declaration: string;
    summary: string;
}

export interface SdkErrorReference {
    code: StudioErrorCode;
    summary: string;
}

export interface SdkReference {
    version: 1;
    namespaces: SdkNamespaceReference[];
    types: SdkTypeReference[];
    errors: SdkErrorReference[];
}

export interface StudioErrorJson {
    name: 'StudioError';
    code: StudioErrorCode;
    message: string;
    argument?: string;
    valid?: readonly string[];
    entity?: EntityRef;
    hint?: string;
}

export interface Studio {
    readonly version: 1;
    readonly project: ProjectApi;
    readonly media: MediaApi;
    readonly subclips: SubclipsApi;
    readonly tracks: TracksApi;
    readonly clips: ClipsApi;
    readonly titles: TitlesApi;
    readonly effects: EffectsApi;
    readonly keyframes: KeyframesApi;
    readonly transitions: TransitionsApi;
    readonly markers: MarkersApi;
    readonly selection: SelectionApi;
    readonly playback: PlaybackApi;
    readonly export: ExportApi;
    readonly history: HistoryApi;
    readonly workspace: WorkspaceApi;
    readonly looks: LooksApi;
    readonly shadow: ShadowApi;
    transaction<T>(label: string, fn: (studio: Studio) => T): TransactionResult<T>;
    reference(): SdkReference;
}
